// Generated by Gemini

// Network-only service worker: UI assets are never cached so clients always load the latest version.
self.addEventListener('install', (event) => {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

self.addEventListener('push', (event) => {
  let notification;
  try {
    notification = event.data?.json()?.notification;
  } catch {
    // Malformed payloads must still produce a visible notification (required by Safari/browsers).
  }

  const readText = (value) =>
    typeof value === 'string' && value.trim().length > 0 ? value : undefined;

  const title = readText(notification?.title) ?? 'Bifrost';
  const options = {
    body: readText(notification?.body) ?? 'Du har modtaget en ny besked. Åbn Bifrost for at se den.',
    tag: readText(notification?.tag),
    icon: '/icons/icon-192.png',
    badge: '/icons/badge-96.png',
    data: notification?.data ?? null,
  };

  event.waitUntil(self.registration.showNotification(title, options));
});

function getTargetPath(data) {
  const isTeacher =
    data?.role === 'teacher' ||
    data?.eventType === 'HelpRequestCreated' ||
    data?.eventType === 'FaqCreated';

  const prefix = isTeacher ? '/teacher' : '';
  const sessionId = data?.sessionId;

  if (typeof sessionId === 'string' && sessionId.trim().length > 0) {
    return `${prefix}/sessions/${sessionId}`;
  }

  return isTeacher ? '/teacher' : '/';
}

self.addEventListener('notificationclick', (event) => {
  event.notification.close();

  event.waitUntil(
    (async () => {
      const scopeUrl = new URL(self.registration.scope);
      const targetUrl = new URL(getTargetPath(event.notification.data), scopeUrl).href;
      const clients = await self.clients.matchAll({
        type: 'window',
        includeUncontrolled: true,
      });

      for (const client of clients) {
        const clientUrl = new URL(client.url);
        if (clientUrl.origin !== scopeUrl.origin || !clientUrl.pathname.startsWith(scopeUrl.pathname)) {
          continue;
        }
        try {
          if (client.url !== targetUrl && 'navigate' in client) {
            await client.navigate(targetUrl);
          }
          await client.focus();
          return;
        } catch {
          // A window may close between matching and focusing it.
        }
      }

      await self.clients.openWindow(targetUrl);
    })(),
  );
});
